exist.go :

package main

import "fmt"

func existsInSlice[T comparable](val T, values []T) bool {
          for _, v := range values {
                    if val == v {
                             return true
                    }
          }
          return false
}

func showIn[T comparable](val T, values []T) {
          fmt.Printf("%v in %v => %v\n", val, values, existsInSlice(val, values))
}

