Один путь состоит в том, чтобы передать переменную в качестве аргумента для замыкания:

closure2.go :

package main

import (
        "fmt"
)

func main() {
        done := make(chan bool)

        values := []string{"a", "b", "c"}
        for _, v := range values {
                go func(u string) {
                        fmt.Println(u)
                        done <- true
                }(v)
        }

        // wait for all goroutines to complete before exiting
        for _ = range values {
                <-done
        }
}

