gotim1.go :

package main
import ("os"; "strconv"; "fmt"; "time")

func sequgo(n int, c chan bool) {
          if n == 0 {
                    c <- true
          } else {
                    go sequgo(n - 1, c)
                    <-c
          }
}

func main() {
          n := 1000
          if len(os.Args) > 1 {
                    n, _ = strconv.Atoi(os.Args[1])
          }
          c := make(chan bool)
          t0 := time.Now()
          sequgo(n, c)
          fmt.Printf("[%d] время выполнения: %v\n", n, time.Now().Sub(t0))
}

Здесь N параллельных go-рутин (N можно указать параметром команды запуска) запускают друг-
друга рекурсивно, по цепочке, и каждая k-я go-рутина, запускающая  (k+1)-ю — ожидает её
завершения. Активировавшись все N ветвей, они начинают так же, по цепочке, в обратном
порядке завершаться.

