Каналы в сопрограммах

Пример использования каналов для взаимного обмена информацией между несколькими go-
процедурами показывает следующий пример (каталог goproc архива):

multy.go :

package main
import (
          "fmt"
          "os"
          "time"
)

func child(num int, in <-chan string, out chan<- string) {
          str1 := fmt.Sprintf("%v : ", num)
          for {
                    str2 := <-in // строка полученная из канал
                    fmt.Println(str1 + str2)
                    if out != nil {
                             out <- str2
                    }            // ретранслируется снова в канал
          }
}

func ввод(ch chan<- string) {
          const per = 300000000
          buf := make([]byte, 1024)
          for {
                    fmt.Printf("> ")
                    n, _ := os.Stdin.Read(buf)
                    str := string(buf[:n-1])
                    fmt.Println(str)
                    ch <- str
                    time.Sleep(per)
          }
}

func main() {
          канал := [...]chan string{
                    make(chan string, 100), make(chan string),
                    make(chan string), make(chan string)}
          for i := range канал {
                    if i != len(канал)-1 {
                             go child(i, канал[i], канал[i+1])
                    } else {
                             go child(i, канал[i], nil)
                    }
          }
          ввод(канал[0])
}

Здесь запускается 4 экземпляра go-процедур (они определяются динамически), параллельно
выполняющих код функции child(). В этом примере демонстрируется, попутно, как каналы
передаются в качестве параметров в функции. Специально показано как в определении функции
каналы маркированы как входной и выходной (альтернативная, необязательная возможность, в
противном случае канал — двунаправленный). Каждый экземпляр (горутина) имеет входной и
выходной канал для передачи символьных сообщений типа string. 1-й экземпляр получает
информацию  по  входному  каналу  от  ввода  с  терминала,  а  дальнейшие  параллельные
сопрограммы передают эту информацию последовательно от экземпляра к экземпляру, по
цепочке: 1 -> 2 -> 3 -> 4 :

$ ./multy
> 1 2 3 4 5
